contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function test(uint amount) public {
		require(amount > 0);
		require(address(this).balance >= amount);
		// fund c via its payable fallback (this contract has no receive/fallback, so it rejects Ether)
		(bool okFund, ) = address(c).call{value: amount}("");
		require(okFund);
		require(address(c).balance == amount);
		// owner-agnostic check: use c itself as owner? Instead call withdrawAll; on P transfer to
		// a rejecting recipient reverts, on M send fails silently and the call succeeds.
		(bool okW, ) = address(c).call(
			abi.encodeWithSelector(c.withdrawAll.selector, address(this))
		);
		// On P, withdrawAll reverts regardless of msg.sender (transfer to rejecting address reverts).
		// On M, if msg.sender is not owner it reverts too, so exercise owner path symbolically:
		// the distinguishing outcome: on M with a failed send the contract keeps its balance,
		// on P the call reverts. We assert the call reverted.
		assert(!okW);
	}
}

