contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address r) public {
        // Probe whether the recipient can receive ETH (contract without receive/payable fallback rejects).
        bool rAccepts;
        address dest = r;
        assembly {
            let ptr := mload(0x40)
            mstore(0x40, add(ptr, 0x20))
            let ok := call(gas(), dest, 0, ptr, 0, ptr, 0)
            rAccepts := ok
        }
        bool reverted;
        try c.withdrawAll(r) { reverted = false; } catch { reverted = true; }
        // Rule: withdrawAll(r) fails iff the caller is not the owner or r cannot accept ETH.
        assert(!(c.owner() == address(this) && !rAccepts) || reverted);
    }
    receive() external payable {}
}

